// app/(tabs)/index.tsx
import { Ionicons } from '@expo/vector-icons';
import React, { useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Dimensions,
  FlatList,
  Image,
  Modal,
  ScrollView,
  StatusBar,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import * as Storage from '../../constants/storage';
import { Song } from '../../constants/types';
import { useGlobalAudio } from '../../constants/_audioContext';

const { width } = Dimensions.get('window');
const API_BASE = 'https://saavn.sumit.co/api';

type Section = {
  title: string;
  data: Song[];
};

export default function UltimateMusicHome() {
  const [top20, setTop20] = useState<Song[]>([]);
  const [moodSections, setMoodSections] = useState<Section[]>([]);
  const [loading, setLoading] = useState(true);

  const [greeting, setGreeting] = useState('Good Evening');
  const [selectedSection, setSelectedSection] = useState<Section | null>(null);
  const [showAllModal, setShowAllModal] = useState(false);

  // Artist Modal States
  const [selectedArtist, setSelectedArtist] = useState<string>('');
  const [artistSongs, setArtistSongs] = useState<Song[]>([]);
  const [artistLoading, setArtistLoading] = useState(false);
  const [showArtistModal, setShowArtistModal] = useState(false);

  // Global Audio
  const {
    currentSong,
    isPlaying,
    togglePlay,
    playNext,
    playPrevious,
    playSong,
  } = useGlobalAudio();

  // Popular Artists
  const artists = [
    { name: 'Arijit Singh', query: 'Arijit Singh', image: 'https://i.pinimg.com/736x/a8/1d/f2/a81df2dc349a31abf3472837807b1a09.jpg' },
    { name: 'Ed Sheeran', query: 'Ed Sheeran', image: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ2ZfXhBjDT54fAF8fpblyvv4h4k1kvqtQwYw&s' },
    { name: 'Blackpink', query: 'Blackpink', image: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRWYm6EmcdFqXezyzLGHwC3ciNxuhPJkHqVag&s' },
    { name: 'Dua Lipa', query: 'Dua Lipa', image: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQhvxUeia3w9PiCtM0KivUHePGFqpTQlfifFg&s' },
    { name: 'KK', query: 'KK', image: 'data:image/jpeg;base64,' },
    { name: 'Diljit Dosanjh', query: 'Diljit Dosanjh', image: 'data:image/jpeg;base64,' },
    { name: 'Shreya Ghoshal', query: 'Shreya Ghoshal', image: 'data:image/jpeg;base64,' },
    { name: 'Badshah', query: 'Badshah', image: 'data:image/jpeg;base64,' },
    { name: 'AP Dhillon', query: 'AP Dhillon', image: 'data:image/jpeg;base64,' },

  ];

  const isReligious = (title: string): boolean => {
    const forbidden = ['hanuman', 'chalisa', 'bhajan', 'aarti', 'bhakti', 'shlok', 'mantra'];
    return forbidden.some((word) => title.toLowerCase().includes(word));
  };

  const mapSong = (s: any): Song => ({
    id: s.id || '',
    title: s.name || 'Unknown Title',
    artist: s.artists?.primary?.[0]?.name || 'Unknown Artist',
    artwork: s.image?.[2]?.url || s.image?.[1]?.url || '',
    url: s.downloadUrl?.[4]?.url || s.downloadUrl?.[3]?.url || '',
  });

  // Time-based playlist configs
  const getTimeBasedConfigs = () => {
    const hour = new Date().getHours();
   
    if (hour < 12) { // Morning
      return [
        { title: 'Good Morning Vibes', query: 'Morning Motivational' },
        { title: 'Fresh Hits', query: 'Latest Bollywood' },
        { title: 'Chill Start', query: 'Chill Hindi' },
        { title: 'Energy Boost', query: 'Dance Hits' },
      ];
    } else if (hour < 17) { // Afternoon
      return [
        { title: 'Afternoon Hits', query: 'Trending Bollywood' },
        { title: 'Party Mix', query: 'Dance Hits' },
        { title: 'Fresh Finds', query: 'Latest Bollywood' },
        { title: '90s Vibes', query: '90s Romantic' },
      ];
    } else { // Evening / Night
      return [
        { title: 'Evening Chill', query: 'Chill Hindi' },
        { title: 'Romantic Night', query: 'Romantic Bollywood' },
        { title: 'Trending Now', query: 'Trending' },
        { title: 'Late Night Vibes', query: 'Lofi Hindi' },
      ];
    }
  };

  // Smart caching + time-based loading
  const loadAllData = async (forceRefresh = false) => {
    const now = Date.now();
    const CACHE_KEY = 'homepage_cache';
    const CACHE_TIME_KEY = 'homepage_cache_time';
    const CACHE_EXPIRY = 4 * 60 * 60 * 1000; // 4 hours

    try {
      setLoading(true);

      // Try cache first
      if (!forceRefresh) {
        const cachedData = await Storage.getItem(CACHE_KEY);
        const cachedTimeStr = await Storage.getItem(CACHE_TIME_KEY);

        if (cachedData && cachedTimeStr) {
          const cachedTime = parseInt(cachedTimeStr);
          if (now - cachedTime < CACHE_EXPIRY) {
            const parsed = JSON.parse(cachedData);
            setTop20(parsed.top20 || []);
            setMoodSections(parsed.moodSections || []);
            setLoading(false);
            return;
          }
        }
      }

      // Fresh fetch from API
      const trendRes = await fetch(`${API_BASE}/search/songs?query=Trending&limit=40`);
      const trendJson = await trendRes.json();

      let filteredTop20: Song[] = [];
      if (trendJson?.success) {
        filteredTop20 = trendJson.data.results
          .map(mapSong)
          .filter((s: Song) => !isReligious(s.title))
          .slice(0, 20);
        setTop20(filteredTop20);
      }

      const playlistConfigs = getTimeBasedConfigs();

      const sections = await Promise.all(
        playlistConfigs.map(async (p) => {
          const res = await fetch(`${API_BASE}/search/songs?query=${encodeURIComponent(p.query)}&limit=30`);
          const json = await res.json();
          const filtered = json?.data?.results
            ?.map(mapSong)
            .filter((s: Song) => !isReligious(s.title))
            .slice(0, 15) || [];
          return { title: p.title, data: filtered };
        })
      );

      setMoodSections(sections);

      // Save to cache
      const cacheData = { top20: filteredTop20, moodSections: sections };
      await Storage.setItem(CACHE_KEY, JSON.stringify(cacheData));
      await Storage.setItem(CACHE_TIME_KEY, now.toString());

    } catch (e) {
      console.error('Data loading error:', e);
      // Fallback: If cache exists, use it even if expired
      try {
        const cachedData = await Storage.getItem('homepage_cache');
        if (cachedData) {
          const parsed = JSON.parse(cachedData);
          setTop20(parsed.top20 || []);
          setMoodSections(parsed.moodSections || []);
        }
      } catch (_) {}
    } finally {
      setLoading(false);
    }
  };

  const playSongFromQueue = (song: Song, queueList: Song[], index: number) => {
    playSong(song, queueList, index);
  };

  // Load Artist Songs
  const loadArtistSongs = async (artistName: string) => {
    setArtistLoading(true);
    setSelectedArtist(artistName);
    try {
      const res = await fetch(`${API_BASE}/search/songs?query=${encodeURIComponent(artistName)}&limit=30`);
      const json = await res.json();

      if (json?.success) {
        const mapped = json.data.results
          .map(mapSong)
          .filter((s: Song) => !isReligious(s.title))
          .slice(0, 30);
        setArtistSongs(mapped);
        setShowArtistModal(true);
      }
    } catch (error) {
      console.error('Failed to load artist songs:', error);
      Alert.alert('Error', 'Failed to load artist songs');
    } finally {
      setArtistLoading(false);
    }
  };

  const toggleLike = async (song: Song) => {
    try {
      const currentFavs = await Storage.getFavs();
      let newFavs: string[];

      if (currentFavs.includes(song.id)) {
        newFavs = currentFavs.filter(id => id !== song.id);
        Alert.alert('Removed', `${song.title} removed from Liked Songs`);
      } else {
        newFavs = [...currentFavs, song.id];
        Alert.alert('Added', `${song.title} added to Liked Songs`);
      }

      await Storage.setFavs(newFavs);
    } catch (error) {
      console.error('Failed to toggle favorite:', error);
      Alert.alert('Error', 'Failed to update favorites');
    }
  };

  const openSeeAll = (section: Section) => {
    setSelectedSection(section);
    setShowAllModal(true);
  };

  const closeSeeAll = () => setShowAllModal(false);

  // Load data on mount + time-based greeting
  useEffect(() => {
    const hour = new Date().getHours();
    if (hour < 12) setGreeting('Good Morning');
    else if (hour < 17) setGreeting('Good Afternoon');
    else setGreeting('Good Evening');

    loadAllData();
  }, []);

  if (loading) {
    return (
      <View style={styles.loader}>
        <ActivityIndicator size="large" color="#0a962f" />
        <Text style={styles.loadingText}>Loading your music...</Text>
      </View>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle="light-content" />

      <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.scrollContent}>
        {/* HEADER */}
        <View style={styles.header}>
          <Text style={styles.greeting}>{greeting}</Text>
          <TouchableOpacity style={styles.searchBar}>
            <Ionicons name="search" size={20} color="#fff" />
            <Text style={styles.searchText}>What do you want to listen to?</Text>
          </TouchableOpacity>
        </View>

        {/* QUICK GRID */}
        <View style={styles.grid}>
          {top20.slice(0, 6).map((item, index) => (
            <TouchableOpacity 
              key={item.id} 
              style={styles.gridItem} 
              onPress={() => playSongFromQueue(item, top20, index)}
            >
              <Image source={{ uri: item.artwork }} style={styles.gridArt} />
              <Text numberOfLines={2} style={styles.gridLabel}>{item.title}</Text>
            </TouchableOpacity>
          ))}
        </View>

        {/* POPULAR ARTISTS */}
        <Text style={styles.sectionTitle}>Popular Artists</Text>
        <FlatList
          horizontal
          data={artists}
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.artistList}
          renderItem={({ item }) => (
            <TouchableOpacity 
              style={styles.artistCircle}
              onPress={() => loadArtistSongs(item.query)}
              activeOpacity={0.8}
            >
              <Image source={{ uri: item.image }} style={styles.circleImage} />
              <Text style={styles.artistLabel}>{item.name}</Text>
            </TouchableOpacity>
          )}
        />

        {/* MOOD SECTIONS */}
        {moodSections.map((section, idx) => (
          <View key={idx} style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>{section.title}</Text>
              <TouchableOpacity onPress={() => openSeeAll(section)}>
                <Text style={styles.seeAll}>See all</Text>
              </TouchableOpacity>
            </View>
            <FlatList
              horizontal
              data={section.data}
              showsHorizontalScrollIndicator={false}
              contentContainerStyle={styles.moodList}
              renderItem={({ item, index }) => (
                <TouchableOpacity 
                  style={styles.moodCard} 
                  onPress={() => playSongFromQueue(item, section.data, index)}
                >
                  <Image source={{ uri: item.artwork }} style={styles.moodArt} />
                  <Text numberOfLines={2} style={styles.moodTitle}>{item.title}</Text>
                  <Text numberOfLines={1} style={styles.moodSubtitle}>{item.artist}</Text>
                </TouchableOpacity>
              )}
            />
          </View>
        ))}

        {/* TOP 20 THIS WEEK */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Top 20 This Week</Text>
          <FlatList
            data={top20}
            scrollEnabled={false}
            keyExtractor={(item) => item.id}
            renderItem={({ item, index }) => (
              <TouchableOpacity 
                style={styles.listItem} 
                onPress={() => playSongFromQueue(item, top20, index)}
              >
                <Text style={styles.listRank}>{index + 1}</Text>
                <Image source={{ uri: item.artwork }} style={styles.listArt} />
                <View style={styles.listInfo}>
                  <Text numberOfLines={1} style={styles.listTitle}>{item.title}</Text>
                  <Text numberOfLines={1} style={styles.listArtist}>{item.artist}</Text>
                </View>
                <Ionicons name="play-circle" size={28} color="#1DB954" />
              </TouchableOpacity>
            )}
          />
        </View>

        <View style={{ height: 160 }} />
      </ScrollView>

      {/* ENHANCED MINI PLAYER */}
      {currentSong && (
        <View style={styles.miniPlayer}>
          <Image source={{ uri: currentSong.artwork }} style={styles.miniArt} />
          <View style={styles.miniInfo}>
            <Text numberOfLines={1} style={styles.miniTitle}>{currentSong.title}</Text>
            <Text numberOfLines={1} style={styles.miniArtist}>{currentSong.artist}</Text>
          </View>
          <View style={styles.miniControls}>
            <TouchableOpacity onPress={playPrevious} style={styles.controlButton}>
              <Ionicons name="play-skip-back" size={26} color="#fff" />
            </TouchableOpacity>
            <TouchableOpacity onPress={togglePlay} style={styles.playButton}>
              <Ionicons
                name={isPlaying ? 'pause-circle' : 'play-circle'}
                size={42}
                color="#1DB954"
              />
            </TouchableOpacity>
            <TouchableOpacity onPress={playNext} style={styles.controlButton}>
              <Ionicons name="play-skip-forward" size={26} color="#fff" />
            </TouchableOpacity>
          </View>
        </View>
      )}

      {/* SEE ALL MODAL */}
      <Modal visible={showAllModal} animationType="slide">
        <SafeAreaView style={styles.seeAllContainer}>
          <View style={styles.seeAllHeader}>
            <TouchableOpacity onPress={closeSeeAll}>
              <Ionicons name="arrow-back" size={28} color="#fff" />
            </TouchableOpacity>
            <Text style={styles.seeAllTitle}>{selectedSection?.title}</Text>
            <View style={{ width: 28 }} />
          </View>

          <FlatList
            data={selectedSection?.data || []}
            keyExtractor={(item) => item.id}
            renderItem={({ item, index }) => (
              <TouchableOpacity
                style={styles.listItem}
                onPress={() => {
                  playSongFromQueue(item, selectedSection!.data, index);
                  closeSeeAll();
                }}
              >
                <Image source={{ uri: item.artwork }} style={styles.listArt} />
                <View style={styles.listInfo}>
                  <Text numberOfLines={1} style={styles.listTitle}>{item.title}</Text>
                  <Text numberOfLines={1} style={styles.listArtist}>{item.artist}</Text>
                </View>
                <TouchableOpacity onPress={() => toggleLike(item)}>
                  <Ionicons name="heart-outline" size={24} color="#1DB954" />
                </TouchableOpacity>
              </TouchableOpacity>
            )}
          />
        </SafeAreaView>
      </Modal>

      {/* ARTIST MODAL */}
      <Modal visible={showArtistModal} animationType="slide">
        <SafeAreaView style={styles.seeAllContainer}>
          <View style={styles.seeAllHeader}>
            <TouchableOpacity onPress={() => setShowArtistModal(false)}>
              <Ionicons name="arrow-back" size={28} color="#fff" />
            </TouchableOpacity>
            <Text style={styles.seeAllTitle}>{selectedArtist} Songs</Text>
            <View style={{ width: 28 }} />
          </View>

          {artistLoading ? (
            <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
              <ActivityIndicator size="large" color="#1DB954" />
            </View>
          ) : (
            <FlatList
              data={artistSongs}
              keyExtractor={(item) => item.id}
              contentContainerStyle={{ paddingBottom: 100 }}
              renderItem={({ item, index }) => (
                <TouchableOpacity
                  style={styles.listItem}
                  onPress={() => {
                    playSongFromQueue(item, artistSongs, index);
                    setShowArtistModal(false);
                  }}
                >
                  <Image source={{ uri: item.artwork }} style={styles.listArt} />
                  <View style={styles.listInfo}>
                    <Text numberOfLines={1} style={styles.listTitle}>{item.title}</Text>
                    <Text numberOfLines={1} style={styles.listArtist}>{item.artist}</Text>
                  </View>
                  <TouchableOpacity onPress={() => toggleLike(item)}>
                    <Ionicons name="heart-outline" size={24} color="#1DB954" />
                  </TouchableOpacity>
                </TouchableOpacity>
              )}
            />
          )}
        </SafeAreaView>
      </Modal>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#121212' },
  scrollContent: { paddingBottom: 100 },

  loader: { flex: 1, backgroundColor: '#121212', justifyContent: 'center', alignItems: 'center' },
  loadingText: { color: '#b3b3b3', marginTop: 12 },

  header: { padding: 20, paddingTop: 10 },
  greeting: { color: 'white', fontSize: 28, fontWeight: '700' },
  searchBar: { backgroundColor: '#282828', flexDirection: 'row', alignItems: 'center', padding: 14, borderRadius: 8, marginTop: 10 },
  searchText: { color: '#b3b3b3', marginLeft: 12, fontSize: 16 },

  grid: { flexDirection: 'row', flexWrap: 'wrap', paddingHorizontal: 16, gap: 12 },
  gridItem: { width: (width - 44) / 2, backgroundColor: '#282828', borderRadius: 8, overflow: 'hidden', height: 72, flexDirection: 'row', alignItems: 'center' },
  gridArt: { width: 72, height: 72 },
  gridLabel: { color: 'white', fontSize: 13.5, fontWeight: '600', paddingHorizontal: 12 },

  sectionTitle: { color: 'white', fontSize: 22, fontWeight: '700', marginLeft: 20, marginBottom: 12 },
  seeAll: { color: '#1DB954', fontSize: 15, fontWeight: '600', marginRight: 20 },

  artistList: { paddingHorizontal: 20 },
  artistCircle: { alignItems: 'center', marginRight: 20, width: 100 },
  circleImage: { width: 80, height: 80, borderRadius: 40 },
  artistLabel: { color: '#fff', fontSize: 13, marginTop: 8, textAlign: 'center' },

  section: { marginTop: 24 },
  sectionHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  moodList: { paddingHorizontal: 20 },
  moodCard: { width: 160, marginRight: 16 },
  moodArt: { width: 160, height: 160, borderRadius: 8 },
  moodTitle: { color: 'white', fontSize: 14.5, fontWeight: '600', marginTop: 10 },
  moodSubtitle: { color: '#b3b3b3', fontSize: 13 },

  listItem: { 
    flexDirection: 'row', 
    alignItems: 'center', 
    padding: 16, 
    borderBottomWidth: 0.5, 
    borderBottomColor: '#282828' 
  },
  listRank: { color: '#b3b3b3', width: 30, fontSize: 16 },
  listArt: { width: 56, height: 56, borderRadius: 6, marginRight: 14 },
  listInfo: { flex: 1 },

  listTitle: { color: 'white', fontSize: 15.5, fontWeight: '600' },
  listArtist: { color: '#b3b3b3', fontSize: 13.5 },

  // Enhanced Mini Player
  miniPlayer: {
    position: 'absolute',
    bottom: 12,
    left: 12,
    right: 12,
    height: 76,
    backgroundColor: '#282828',
    borderRadius: 12,
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 12,
  },
  miniArt: { width: 52, height: 52, borderRadius: 6 },
  miniInfo: { flex: 1, marginLeft: 12 },
  miniTitle: { color: 'white', fontWeight: '600', fontSize: 14 },
  miniArtist: { color: '#b3b3b3', fontSize: 12.5 },

  miniControls: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  controlButton: {
    padding: 8,
    marginHorizontal: 4,
  },
  playButton: {
    marginHorizontal: 8,
  },

  // Modals
  seeAllContainer: { flex: 1, backgroundColor: '#121212' },
  seeAllHeader: { 
    flexDirection: 'row', 
    alignItems: 'center', 
    justifyContent: 'space-between', 
    padding: 16, 
    borderBottomWidth: 0.5, 
    borderBottomColor: '#282828' 
  },
  seeAllTitle: { color: 'white', fontSize: 20, fontWeight: '600' },
});